const { useEffect, useRef, useState } = React;

const BRUSH_MODES = [
  { key: 'pen', label: '펜', icon: '✏️' },
  { key: 'neon', label: '네온', icon: '✨' },
  { key: 'rainbow', label: '무지개', icon: '🌈' },
  { key: 'eraser', label: '지우개', icon: '🧽' },
];

const BRUSH_SIZES = [3, 6, 12, 22, 36];

function ModeButton({ mode, active, onClick }) {
  return (
    <button
      onClick={onClick}
      className={`flex flex-col items-center justify-center gap-1 py-2.5 rounded-xl text-xs font-semibold transition-all ${
        active
          ? 'bg-gradient-to-br from-indigo-500 to-fuchsia-500 text-white shadow-lg shadow-fuchsia-500/30 scale-105'
          : 'bg-white/5 text-slate-300 hover:bg-white/10'
      }`}
    >
      <span className="text-lg">{mode.icon}</span>
      {mode.label}
    </button>
  );
}

function App() {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const cursorRef = useRef(null);
  const ctxRef = useRef(null);

  // 캔버스 픽셀 크기 (컨테이너에 맞춰 동적)
  const dimsRef = useRef({ w: 0, h: 0 });
  const [dims, setDims] = useState({ w: 0, h: 0 });

  // 입력값은 모두 ref에 (리렌더 방지)
  const joyRef = useRef({ x: 0, y: 0 });
  const penDownRef = useRef(false);
  const hueRef = useRef(200);
  const rainbowHueRef = useRef(0);

  // 커서 위치 / 직전 위치
  const posRef = useRef({ x: 0, y: 0 });
  const lastDrawRef = useRef(null);

  // 설정 ref (루프에서 읽음)
  const modeRef = useRef('pen');
  const brushRef = useRef(6);
  const mirrorRef = useRef(false);
  const darkBgRef = useRef(true);

  // HUD 표시용 (가끔만 setState)
  const [penDown, setPenDown] = useState(false);
  const [hue, setHue] = useState(200);
  const [brush, setBrush] = useState(6);
  const [mode, setMode] = useState('pen');
  const [mirror, setMirror] = useState(false);
  const [darkBg, setDarkBg] = useState(true);
  const lastHudRef = useRef(0);

  // 되돌리기 스냅샷
  const undoStackRef = useRef([]);
  const [canUndo, setCanUndo] = useState(false);

  useEffect(() => { brushRef.current = brush; }, [brush]);
  useEffect(() => { modeRef.current = mode; }, [mode]);
  useEffect(() => { mirrorRef.current = mirror; }, [mirror]);

  const paintBg = (ctx, dark, w, h) => {
    ctx.save();
    ctx.fillStyle = dark ? '#0b1020' : '#ffffff';
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  };

  // 컨테이너 크기에 맞춰 캔버스 크기 측정 (반응형)
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;

    const applySize = () => {
      const rect = wrap.getBoundingClientRect();
      const w = Math.max(100, Math.round(rect.width));
      const h = Math.max(100, Math.round(rect.height));
      const prev = dimsRef.current;
      if (w === prev.w && h === prev.h) return;

      const canvas = canvasRef.current;
      let ctx = ctxRef.current;

      // 기존 그림 보존
      let snap = null;
      if (ctx && prev.w > 0 && prev.h > 0) {
        try { snap = ctx.getImageData(0, 0, prev.w, prev.h); } catch (e) {}
      }

      canvas.width = w;
      canvas.height = h;
      ctx = canvas.getContext('2d');
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctxRef.current = ctx;

      paintBg(ctx, darkBgRef.current, w, h);
      if (snap) {
        try { ctx.putImageData(snap, 0, 0); } catch (e) {}
      } else {
        posRef.current = { x: w / 2, y: h / 2 };
      }

      dimsRef.current = { w, h };
      setDims({ w, h });
      lastDrawRef.current = null;
    };

    applySize();
    const ro = new ResizeObserver(applySize);
    ro.observe(wrap);
    return () => ro.disconnect();
  }, []);

  const pushUndo = () => {
    const ctx = ctxRef.current;
    const { w, h } = dimsRef.current;
    if (!ctx || w === 0) return;
    try {
      const snap = ctx.getImageData(0, 0, w, h);
      undoStackRef.current.push(snap);
      if (undoStackRef.current.length > 20) undoStackRef.current.shift();
      setCanUndo(true);
    } catch (e) {}
  };

  // 조이스틱 입력 (속도형 이동)
  useEffect(() => {
    const offX = MODI.onValue('joystick', 1, 'x', (v) => { joyRef.current.x = v || 0; }, { pollMs: 30 });
    const offY = MODI.onValue('joystick', 1, 'y', (v) => { joyRef.current.y = v || 0; }, { pollMs: 30 });
    return () => { offX(); offY(); };
  }, []);

  // 다이얼 -> 색(Hue)
  useEffect(() => {
    const offDial = MODI.onValue('dial', 1, 'turn', (v) => {
      const h = ((v || 0) % 360 + 360) % 360;
      hueRef.current = h;
      const now = performance.now();
      if (now - lastHudRef.current > 150) {
        lastHudRef.current = now;
        setHue(Math.round(h));
      }
    }, { pollMs: 60 });
    return () => { offDial(); };
  }, []);

  // 버튼 -> 펜 내림/올림 (토글). 내릴 때 스냅샷 저장
  const btn = useButton(1);
  useEffect(() => {
    if (btn.clicked) {
      const next = !penDownRef.current;
      if (next) pushUndo();
      penDownRef.current = next;
      setPenDown(next);
      lastDrawRef.current = null;
    }
  }, [btn.clicked]);

  // 메인 루프: 커서 이동 + 그리기
  useEffect(() => {
    let raf;
    let prevTime = performance.now();
    const CURSOR_SIZE = 18;
    const DEAD = 8;
    const SPEED = 0.4;

    const drawSeg = (ctx, ax, ay, bx, by) => {
      ctx.beginPath();
      ctx.moveTo(ax, ay);
      ctx.lineTo(bx, by);
      ctx.stroke();
    };

    const loop = () => {
      const now = performance.now();
      const dt = Math.min(now - prevTime, 50);
      prevTime = now;

      const { w: W, h: H } = dimsRef.current;
      if (W === 0) { raf = requestAnimationFrame(loop); return; }

      const pos = posRef.current;
      const joy = joyRef.current;

      const jx = Math.abs(joy.x) < DEAD ? 0 : joy.x / 100;
      const jy = Math.abs(joy.y) < DEAD ? 0 : joy.y / 100;

      pos.x = Math.max(0, Math.min(W, pos.x + jx * SPEED * dt));
      pos.y = Math.max(0, Math.min(H, pos.y - jy * SPEED * dt));

      rainbowHueRef.current = (rainbowHueRef.current + dt * 0.15) % 360;

      if (penDownRef.current && ctxRef.current) {
        const ctx = ctxRef.current;
        const last = lastDrawRef.current;
        const m = modeRef.current;
        const size = brushRef.current;

        let color;
        let lineWidth = size;
        ctx.shadowBlur = 0;
        ctx.shadowColor = 'transparent';

        if (m === 'eraser') {
          color = darkBgRef.current ? '#0b1020' : '#ffffff';
          lineWidth = size * 1.8;
        } else if (m === 'rainbow') {
          color = `hsl(${rainbowHueRef.current}, 90%, 55%)`;
        } else if (m === 'neon') {
          color = `hsl(${hueRef.current}, 95%, 60%)`;
          ctx.shadowBlur = size * 2.2;
          ctx.shadowColor = color;
        } else {
          color = `hsl(${hueRef.current}, 85%, 52%)`;
        }

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = lineWidth;

        if (last) {
          drawSeg(ctx, last.x, last.y, pos.x, pos.y);
          if (m === 'neon') drawSeg(ctx, last.x, last.y, pos.x, pos.y);
          if (mirrorRef.current) {
            drawSeg(ctx, W - last.x, last.y, W - pos.x, pos.y);
            if (m === 'neon') drawSeg(ctx, W - last.x, last.y, W - pos.x, pos.y);
          }
        } else {
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, lineWidth / 2, 0, Math.PI * 2);
          ctx.fill();
          if (mirrorRef.current) {
            ctx.beginPath();
            ctx.arc(W - pos.x, pos.y, lineWidth / 2, 0, Math.PI * 2);
            ctx.fill();
          }
        }
        ctx.shadowBlur = 0;
        lastDrawRef.current = { x: pos.x, y: pos.y };
      } else {
        lastDrawRef.current = null;
      }

      if (cursorRef.current) {
        cursorRef.current.style.transform =
          `translate3d(${pos.x - CURSOR_SIZE / 2}px, ${pos.y - CURSOR_SIZE / 2}px, 0)`;
      }

      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const clearCanvas = () => {
    const ctx = ctxRef.current;
    const { w, h } = dimsRef.current;
    if (!ctx) return;
    pushUndo();
    paintBg(ctx, darkBgRef.current, w, h);
    lastDrawRef.current = null;
  };

  const togglePen = () => {
    const next = !penDownRef.current;
    if (next) pushUndo();
    penDownRef.current = next;
    setPenDown(next);
    lastDrawRef.current = null;
  };

  const undo = () => {
    const ctx = ctxRef.current;
    const stack = undoStackRef.current;
    if (!ctx || stack.length === 0) return;
    const snap = stack.pop();
    try { ctx.putImageData(snap, 0, 0); } catch (e) {}
    setCanUndo(stack.length > 0);
    lastDrawRef.current = null;
  };

  const toggleBg = () => {
    const ctx = ctxRef.current;
    const { w, h } = dimsRef.current;
    if (!ctx) return;
    const next = !darkBgRef.current;
    darkBgRef.current = next;
    setDarkBg(next);
    pushUndo();
    paintBg(ctx, next, w, h);
    lastDrawRef.current = null;
  };

  const toggleMirror = () => {
    const next = !mirrorRef.current;
    mirrorRef.current = next;
    setMirror(next);
  };

  const saveImage = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = 'modi-art.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const activeColor =
    mode === 'rainbow'
      ? 'conic-gradient(red, orange, yellow, lime, cyan, blue, magenta, red)'
      : mode === 'eraser'
      ? '#94a3b8'
      : `hsl(${hue}, 90%, 55%)`;

  return (
    <div className="h-screen flex flex-col p-5 text-slate-100 bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900">
      <div className="flex-shrink-0 flex items-center justify-between mb-4">
        <div>
          <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-300 to-fuchsia-300 bg-clip-text text-transparent">
            ✨ 모디 네온 그림판
          </h1>
          <p className="text-sm text-slate-400">조이스틱으로 이동 · 버튼으로 펜 · 다이얼로 색 변경</p>
        </div>
        <div className="flex items-center gap-3">
          <div
            className="w-10 h-10 rounded-full border-2 border-white/30 shadow-lg"
            style={{ background: activeColor }}
          />
          <span
            className={`px-3 py-1.5 rounded-full text-sm font-semibold transition-colors ${
              penDown ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/30' : 'bg-white/10 text-slate-400'
            }`}
          >
            {penDown ? '● 그리는 중' : '○ 펜 올림'}
          </span>
        </div>
      </div>

      <div className="flex-1 min-h-0 flex gap-5">
        <div
          ref={wrapRef}
          className="relative flex-1 min-w-0 rounded-2xl shadow-2xl overflow-hidden ring-1 ring-white/10"
        >
          <canvas ref={canvasRef} className="block w-full h-full" />
          {mirror && (
            <div className="absolute top-0 bottom-0 left-1/2 w-px bg-white/20 pointer-events-none" />
          )}
          <div
            ref={cursorRef}
            className="absolute pointer-events-none rounded-full border-2"
            style={{
              left: 0,
              top: 0,
              width: 18,
              height: 18,
              borderColor: penDown ? 'rgba(16,185,129,0.95)' : 'rgba(255,255,255,0.8)',
              willChange: 'transform',
              boxShadow: '0 0 0 2px rgba(0,0,0,0.35)',
            }}
          />
        </div>

        <div className="w-72 flex-shrink-0 flex flex-col gap-3 overflow-y-auto">
          <div className="bg-white/5 backdrop-blur rounded-2xl p-4 ring-1 ring-white/10">
            <p className="text-sm font-semibold text-slate-300 mb-2">붓 모드</p>
            <div className="grid grid-cols-4 gap-2">
              {BRUSH_MODES.map((m) => (
                <ModeButton key={m.key} mode={m} active={mode === m.key} onClick={() => setMode(m.key)} />
              ))}
            </div>
          </div>

          <div className="bg-white/5 backdrop-blur rounded-2xl p-4 ring-1 ring-white/10">
            <p className="text-sm font-semibold text-slate-300 mb-2">붓 굵기</p>
            <div className="flex gap-2">
              {BRUSH_SIZES.map((size) => (
                <button
                  key={size}
                  onClick={() => setBrush(size)}
                  className={`flex-1 py-2 rounded-xl text-sm font-medium transition-all ${
                    brush === size
                      ? 'bg-gradient-to-br from-indigo-500 to-fuchsia-500 text-white shadow-lg'
                      : 'bg-white/5 text-slate-300 hover:bg-white/10'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={togglePen}
              className="py-3 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-white font-semibold transition-colors"
            >
              펜 내림/올림
            </button>
            <button
              onClick={toggleMirror}
              className={`py-3 rounded-xl font-semibold transition-colors ${
                mirror ? 'bg-fuchsia-500 text-white' : 'bg-white/10 text-slate-300 hover:bg-white/20'
              }`}
            >
              🪞 좌우대칭
            </button>
            <button
              onClick={undo}
              disabled={!canUndo}
              className={`py-3 rounded-xl font-semibold transition-colors ${
                canUndo ? 'bg-white/10 text-slate-200 hover:bg-white/20' : 'bg-white/5 text-slate-600 cursor-not-allowed'
              }`}
            >
              ↩︎ 되돌리기
            </button>
            <button
              onClick={toggleBg}
              className="py-3 rounded-xl bg-white/10 text-slate-200 hover:bg-white/20 font-semibold transition-colors"
            >
              {darkBg ? '🌙 어두운 배경' : '☀️ 밝은 배경'}
            </button>
            <button
              onClick={clearCanvas}
              className="py-3 rounded-xl bg-rose-500 hover:bg-rose-400 text-white font-semibold transition-colors"
            >
              🗑 전체 지우기
            </button>
            <button
              onClick={saveImage}
              className="py-3 rounded-xl bg-gradient-to-br from-indigo-500 to-fuchsia-500 text-white font-semibold shadow-lg"
            >
              💾 저장하기
            </button>
          </div>

          <div className="bg-white/5 backdrop-blur rounded-2xl p-4 ring-1 ring-white/10 text-sm text-slate-400 leading-relaxed mt-auto">
            <p className="font-semibold text-slate-300 mb-1">사용법</p>
            <p>조이스틱: 펜 이동</p>
            <p>버튼: 펜 내림/올림</p>
            <p>다이얼: 색깔 ({hue}°)</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
